import com.sap.it.api.mapping.*;def void GetLast2chars(String[] input, Output output, MappingContext context) {    String fullString = input[0];    if (fullString != null && fullString.contains("/")) {        String[] parts = fullString.split("/");        String lastPart = parts[parts.length - 1];        String result = lastPart.length() >= 2 ? lastPart[-2..-1] : lastPart;        output.addValue(result);    } else {        output.addValue("");    }}